function policyHref(iri: string): string {
  const u = new URLSearchParams(typeof location === 'undefined' ? '' : location.search);
  u.set('policy', iri);
  return '?' + u.toString();
}

// A real ?policy= link, so middle-click and copy keep working; a plain click is
// intercepted and only falls through when the target card cannot be found.
export function CardJump(props: {
  iri: string; title?: string | null; class?: string; children?: JSX.Element;
}): JSX.Element {
  return (
    <a
      href={policyHref(props.iri)}
      class={props.class ? 'card-jump ' + props.class : 'card-jump'}
      title={props.title || undefined}
      onClick={(e) => {
        if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button) return;
        e.preventDefault();
        const href = (e.currentTarget as HTMLAnchorElement).href;
        Promise.resolve(jump(props.iri, { smooth: true })).then((ok) => {
          if (!ok && typeof location !== 'undefined') location.href = href;
        }).catch(() => {});
      }}
    >{props.children}</a>
  );
}

export function Ref(props: { agent?: Party | null }): JSX.Element {
  const name = () => {
    const a = props.agent;
    return a && a.label && a.label !== a.curie ? a.label : null;
  };
  const tag = (a: Party) => (iri: string | null) => (
    <span data-iri={iri || undefined}>
      <Show when={name()}>{(l) => <>{l()}{' '}</>}</Show>
      <span class="mono muted">{iri ? a.curie : ''}</span>
    </span>
  );
  const collTag = (a: Party) => (iri: string | null) => (
    <span data-iri={iri || undefined}>
      <Field spec={{
        term: iri || (a as { term?: unknown }).term,
        kind: 'text',
        preds: PRED.TITLE,
        value: name() ?? '',
        hint: text('edit.hintGroupName'),
        focusKey: focusAddress(iri || (a as { term?: unknown }).term),
      }}
      >
        <Show when={name()}>{(l) => <>{l()}{' '}</>}</Show>
      </Field>
      <span class="mono muted">{iri ? a.curie : ''}</span>
      <Show when={!iri && (a as { term?: unknown }).term}>
        <Field spec={{
          term: (a as { term?: unknown }).term,
          kind: 'iri',
          preds: [],
          variant: 'nodeIri',
          iri: null,
        }}
        />
      </Show>
    </span>
  );
  const collection = () => {
    const a = props.agent as (Party & CollectionNode) | null | undefined;
    return a && (a.intension || (a.members || []).length || a.collKind) ? a : null;
  };
  return (
    <Show when={props.agent}>{(a) => (
      <Show when={collection()} fallback={tag(a())(a().iri || null)}>{(c) => (
        <span class="party-coll"><Collection desc={c()} tag={collTag(a())} /></span>
      )}</Show>
    )}</Show>
  );
}

export function refLabel(d: Reference): string {
  let label = d.label || d.curie || d.iri;
  if (/%[0-9A-Fa-f]{2}/.test(label)) {
    try { label = decodeURIComponent(label); } catch {}
  }
  return label;
}

function isPolicy(iri: string): boolean {
  const m = model() as any;
  if (!m) return false;
  return [...m.sets, ...m.offers, ...m.agreements].some((p: Policy) => p.iri === iri);
}

export function ProvRef(props: { d: Reference }): JSX.Element {
  const external = () => /^https?:/.test(props.d.iri) && !isPolicy(props.d.iri);
  const curieBeside = () => {
    const c = props.d.curie;
    return c && c !== refLabel(props.d) && !/^https?:/.test(c) ? c : null;
  };
  const inGraph = () => {
    void graphVersion();
    const g = graph();
    return !!g && isGraphSubject(g, props.d.iri);
  };
  return (
    <Show
      when={!external()}
      fallback={(
        <span>
          <a href={props.d.iri} target="_blank" rel="noopener">{refLabel(props.d)}</a>
        </span>
      )}
    >
      <span>
        <Show when={isPolicy(props.d.iri)} fallback={refLabel(props.d)}>
          <a href={policyHref(props.d.iri)}>{refLabel(props.d)}</a>
        </Show>
        <Show when={curieBeside()}>{(c) => <>{' '}<span class="mono muted">{c()}</span></>}</Show>
      </span>
    </Show>
  );
}

export function ProvRefs(props: { list?: Reference[] | null; cls?: string }): JSX.Element {
  return (
    <Show when={(props.list || []).length}>
      <span class={props.cls || undefined}>
        <For each={props.list}>{(d, i) => (
          <>{i() ? '; ' : ''}<ProvRef d={d} /></>
        )}</For>
      </span>
    </Show>
  );
}

function OfferLinks(props: { iris?: string[] }): JSX.Element {
  const m = () => model() as any;
  const title = (iri: string) => {
    const off = m() && m().offers.find((o: Policy) => o.iri === iri);
    return (off && off.title) || curie(iri);
  };
  return (
    <Show when={(props.iris || []).length}>
      <span>
        <For each={props.iris}>{(iri, i) => (
          <>{i() ? ', ' : ''}<a href={policyHref(iri)}>{title(iri)}</a></>
        )}</For>
      </span>
    </Show>
  );
}

function RequestLine(props: { list?: Reference[] | null }): JSX.Element {
  const items = () => (props.list || []).filter(Boolean) as any[];
  const parts = (r: any): JSX.Element[] => {
    const out: JSX.Element[] = [];
    if (r.identifier) out.push(<span class="mono muted doc-ref">{r.identifier}</span>);
    const d = dayDate(r.issued);
    if (d) out.push(<span class="muted">{d}</span>);
    if (r.requester && r.requester.label) out.push(<span>{r.requester.label}</span>);
    if (!out.length) out.push(<span>{r.title || r.label || r.curie || r.iri}</span>);
    return out;
  };
  return (
    <Show when={items().length}>
      <span>
        <For each={items()}>{(r, i) => (
          <>
            {i() ? '; ' : ''}
            <span class="req-line" title={text('request.title')}>
              <CardJump iri={r.iri} title={text('jump.toRequest')}>
                <For each={parts(r)}>{(s, j) => <>{j() ? ' · ' : ''}{s}</>}</For>
              </CardJump>
              <Show when={((r.asksFor || []) as Reference[]).filter((a) => a && a.iri).length}>
                {' · '}<AsksFor list={r.asksFor} />
              </Show>
            </span>
          </>
        )}</For>
      </span>
    </Show>
  );
}

const SLOT = '\u0000';

export function AsksFor(props: { list?: Reference[] | null }): JSX.Element {
  const items = () => (props.list || []).filter((a) => a && a.iri);
  const m = () => model() as any;
  const hasCard = (iri: string) => !!(m() && m().offers.some((o: Policy) => o.iri === iri));
  const name = (a: Reference) => {
    const off = m() && m().offers.find((o: Policy) => o.iri === a.iri);
    return (off && off.title) || a.label || a.curie || a.iri;
  };
  const parts = () => text('askOffer.line', { offer: SLOT }).split(SLOT);
  return (
    <Show when={items().length}>
      <span class="asks-for-line">
        <For each={items()}>{(a, i) => (
          <>
            {i() ? '; ' : ''}
            <span class="asks-for" title={text('askOffer.title')}>
              <span>{parts()[0]}</span>
              <Show
                when={hasCard(a.iri)}
                fallback={<span class="asks-offer">{name(a)}</span>}
              >
                <a href={policyHref(a.iri)}>{name(a)}</a>
              </Show>
              <Show when={parts()[1]}>{(tail) => <span>{tail()}</span>}</Show>
            </span>
          </>
        )}</For>
      </span>
    </Show>
  );
}

export function DecidedIn(props: { iri?: string | null }): JSX.Element {
  const items = () => {
    const m = model() as any;
    if (!m || !props.iri) return [];
    return (agreementsByRequest(m).get(props.iri) || []) as Reference[];
  };
  const parts = () => text('decidedIn.line', { agreement: SLOT }).split(SLOT);
  return (
    <Show when={items().length}>
      <span class="answered-by-line">
        <For each={items()}>{(a, i) => (
          <>
            {i() ? '; ' : ''}
            <span class="answered-by" title={text('decidedIn.title')}>
              <span>{parts()[0]}</span>
              <CardJump iri={a.iri} title={text('jump.toAgreement')}>
                <span>{a.title || a.curie || a.iri}</span>
              </CardJump>
              <Show when={parts()[1]}>{(tail) => <span>{tail()}</span>}</Show>
            </span>
          </>
        )}</For>
      </span>
    </Show>
  );
}

export function versionLine(v?: Version | null): string | null {
  if (!v) return null;
  const parts: string[] = [];
  if (v.effectiveFrom) parts.push(text('vline.validFrom', { date: v.effectiveFrom }));
  if (v.effectiveTo) parts.push(text('vline.validTo', { date: v.effectiveTo }));
  if (v.revisionOf) {
    parts.push(text('vline.replaces', { refs: v.revisionOf.label || v.revisionOf.curie }));
  }
  if (v.supersededBy && v.supersededBy.length) {
    parts.push(text('vline.supersededBy', {
      refs: v.supersededBy.map((s) => s.label || s.curie).join('; '),
    }));
  }
  if (v.derivedFrom && v.derivedFrom.length) {
    parts.push(text('vline.derivedFrom', {
      refs: v.derivedFrom.map((d) => d.label || d.curie).join('; '),
    }));
  }
  return parts.length ? parts.join(' · ') : null;
}

function RequestSubtitle(props: { pol: Policy }): JSX.Element {
  const parts = (): JSX.Element[] => {
    const out: JSX.Element[] = [];
    const p = props.pol;
    if (p.identifier) out.push(<span class="mono muted doc-ref">{p.identifier}</span>);
    const d = dayDate(p.issued);
    if (d) out.push(<span class="muted">{d}</span>);
    const who = policyAssignee(p) as Party | null;
    const name = who && (who.label || who.curie || who.iri);
    if (name) out.push(<span>{name}</span>);
    return out;
  };
  return (
    <Show when={parts().length}>
      <p class="req-sub">
        <For each={parts()}>{(s, i) => <>{i() ? ' · ' : ''}{s}</>}</For>
      </p>
    </Show>
  );
}

function datasetOf(pol: Policy): any {
  const m = model() as any;
  if (!m) return null;
  return m.datasets.find((d: any) => d.iri === pol.datasetIri
    || (d.policies || []).includes(pol.iri)) || null;
}

function profileValue(pol: Policy): JSX.Element | null {
  return pol.profile ? <span class="mono muted">{curie(pol.profile)}</span> : null;
}

function identifierValue(pol: Policy): JSX.Element | null {
  return pol.identifier ? <span class="mono muted doc-ref">{pol.identifier}</span> : null;
}

const LEGAL_BASIS_IRI = 'https://w3id.org/dpv#hasLegalBasis';
const SOURCE_IRI = 'http://purl.org/dc/terms/source';
const LINKED_KEY: Record<string, string> = {
  [LEGAL_BASIS_IRI]: 'field.legalBasis', [SOURCE_IRI]: 'field.origin',
};

export interface ExtraProperty {
  predicate: { iri: string; curie: string; label: string };
  values: { literal?: string; blank?: boolean; iri?: string; curie?: string; label?: string }[];
}

export function legalBasisFirst(list: ExtraProperty[]): ExtraProperty[] {
  const gr = list.filter((ep) => ep.predicate.iri === LEGAL_BASIS_IRI);
  const br = list.filter((ep) => ep.predicate.iri === SOURCE_IRI);
  if (!gr.length || !br.length) return list;
  const rest = list.filter((ep) => !gr.includes(ep) && !br.includes(ep));
  const op = Math.min(list.indexOf(gr[0]), list.indexOf(br[0]));
  const before = list.slice(0, op).filter((ep) => rest.includes(ep));
  return [...before, ...gr, ...br, ...rest.slice(before.length)];
}

function ExtraValueText(props: {
  v: ExtraProperty['values'][number]; source: boolean;
}): JSX.Element {
  return (
    <Show
      when={props.v.literal === undefined}
      fallback={<LongText text={props.v.literal} />}
    >
      <Show when={!props.v.blank} fallback={<span class="blank-summary">{props.v.label}</span>}>
        <Show
          when={props.source && /^https?:/.test(props.v.iri || '')}
          fallback={(
            <span title={props.v.iri}>
              {props.v.label}{' '}<span class="mono muted">{props.v.curie}</span>
            </span>
          )}
        >
          <a href={props.v.iri} target="_blank" rel="noopener">{props.v.label}</a>
        </Show>
      </Show>
    </Show>
  );
}

function extraValue(ep: ExtraProperty, spotOf: string): JSX.Element {
  const spot = `${spotOf}#${ep.predicate.iri}`;
  const source = !!LINKED_KEY[ep.predicate.iri];
  const covered = () => ep.values.some((v) => v.iri && coversNode(v.iri));
  return (
    <Show when={!covered()} fallback={(
      <div class="node-folds">
        <NodeChain.Provider value={[spot]}>
          <For each={ep.values}>{(v) => (
            <NodeFold iri={v.iri}><ExtraValueText v={v} source={source} /></NodeFold>
          )}</For>
        </NodeChain.Provider>
      </div>
    )}
    >
      <span>
        <For each={ep.values}>{(v, i) => (
          <>
            {i() ? (source ? '; ' : ', ') : ''}
            <ExtraValueText v={v} source={source} />
          </>
        )}</For>
      </span>
    </Show>
  );
}

function extraSpec(ep: ExtraProperty, term: unknown): {
  kind: 'text' | 'iri'; notApplicable?: string; value?: string | null; iri?: string | null;
} {
  const v = ep.values[0];
  if (ep.values.length > 1) {
    return { kind: 'text', notApplicable: text('edit.fieldMultiValued'), value: null };
  }
  if (!v) return { kind: 'text', notApplicable: text('edit.fieldAlreadyEmpty'), value: null };
  if (v.blank) return { kind: 'text', notApplicable: text('edit.fieldBlank'), value: null };
  if (v.literal !== undefined) return { kind: 'text', value: v.literal };
  return { kind: 'iri', iri: v.iri ?? null };
}

export function extraRows(
  list?: ExtraProperty[] | null, term?: unknown, spot?: string,
): KvRow[] {
  return legalBasisFirst(list || []).map((ep) => {
    const key = LINKED_KEY[ep.predicate.iri];
    const readNode = extraValue(ep, spot ?? String(term ?? ''));
    const spec = extraSpec(ep, term);
    return {
      key,
      label: key ? undefined : ep.predicate.label,
      value: term === undefined ? readNode : (
        <Field spec={{
          term,
          kind: spec.kind,
          preds: [ep.predicate.iri],
          value: spec.value,
          iri: spec.iri,
          category: 'labeled',
          notApplicable: spec.notApplicable,
          label: key ? text(key) : ep.predicate.label,
        }}
        >{readNode}</Field>
      ),
    } as KvRow;
  });
}

function nodeOf(pol: Policy): unknown {
  return pol.anon ? (pol as { term?: unknown }).term : pol.iri;
}

function textField(pol: Policy, preds: readonly string[], value: string | null | undefined,
  readNode: JSX.Element): JSX.Element {
  return <Field spec={{ term: nodeOf(pol), kind: 'text', preds, value }}>{readNode}</Field>;
}

function dateField(pol: Policy, preds: readonly string[], value: string | null | undefined,
  readNode: JSX.Element): JSX.Element {
  return <Field spec={{ term: nodeOf(pol), kind: 'date', preds, value }}>{readNode}</Field>;
}

function partyField(pol: Policy, preds: readonly string[], party: Party | null | undefined,
  readNode: JSX.Element, notApplicable?: string, hint?: string): JSX.Element {
  return (
    <Field spec={{
      term: nodeOf(pol), kind: 'iri', preds, iri: party?.iri ?? null,
      category: 'parties', notApplicable, hint, newGroup: true,
    }}
    >{readNode}</Field>
  );
}

function partyRow(pol: Policy, key: string, preds: readonly string[],
  party: Party | null | undefined, hintKey: string, notApplicable?: string): KvRow {
  const show = party || editLayerActive();
  return {
    key,
    value: show
      ? partyField(pol, preds, party, party ? <Ref agent={party} /> : <></>,
        notApplicable, text(hintKey))
      : null,
    ref: party?.iri,
  };
}

// Kv contract: an empty row must be null, never a component that renders nothing —
// in Solid both are objects, so Kv would draw an empty dt/dd pair.
function listOrNull<T>(list: T[] | null | undefined,
  make: (l: T[]) => JSX.Element): JSX.Element | null {
  return list && list.length ? make(list) : null;
}

function offerRows(pol: Policy): KvRow[] {
  const ds = datasetOf(pol);
  return [
    partyRow(pol, 'field.assigner', PRED.ASSIGNER, pol.assigner, 'edit.hintAssigner'),
    {
      label: text('field.dataset'),
      value: ds ? <span>{ds.title}{' '}<span class="mono muted">{ds.curie}</span></span> : null,
      ref: ds ? ds.iri : null,
    },
    { key: 'field.issued', value: issuedRow(pol) },
    { key: 'field.derivedFrom', value: listOrNull(pol.version?.derivedFrom, (l) => <ProvRefs list={l} />) },
    { key: 'field.profile', value: profileValue(pol) },
    { key: 'field.reference', value: identifierRow(pol) },
  ];
}

function issuedRow(pol: Policy): JSX.Element | null {
  if (!pol.issued) return null;
  return dateField(pol, PRED.ISSUED, pol.issued, <>{pol.issued}</>);
}

function identifierRow(pol: Policy): JSX.Element | null {
  const readNode = identifierValue(pol);
  if (!readNode) return null;
  return textField(pol, PRED.IDENTIFIER, pol.identifier, readNode);
}

function agreementRows(pol: Policy, detail: boolean): KvRow[] {
  const requestIris = new Set((pol.requests || []).map((r) => r.iri));
  const m = model() as any;
  const derived = (pol.version?.derivedFrom || []).filter((d) => !(pol.offers || []).includes(d.iri)
    && !requestIris.has(d.iri)
    && !(m && m.offers.some((o: Policy) => o.iri === d.iri)));
  return [
    partyRow(pol, 'field.assignee', PRED.ASSIGNEE, pol.assignee, 'edit.hintAssignee'),
    detail || editLayerActive()
      ? partyRow(pol, 'field.assigner', PRED.ASSIGNER, pol.assigner, 'edit.hintAssigner')
      : { key: 'field.assigner', value: null, ref: pol.assigner?.iri },
    { key: 'field.issued', value: issuedRow(pol) },
    {
      key: 'field.replaces',
      value: pol.version?.revisionOf ? <ProvRef d={pol.version.revisionOf} /> : null,
      ref: pol.version?.revisionOf?.iri,
    },
    { key: 'field.derivedFrom', value: listOrNull(derived, (l) => <ProvRefs list={l} />) },
    {
      key: 'field.fulfilsOffer',
      value: detail ? listOrNull(pol.offers, (l) => <OfferLinks iris={l} />) : null,
    },
    { key: 'field.request', value: listOrNull(pol.requests, (l) => <RequestLine list={l} />) },
    { key: 'field.profile', value: detail ? profileValue(pol) : null },
    { key: 'field.reference', value: identifierRow(pol) },
  ];
}

function setRows(pol: Policy, compact: boolean): KvRow[] {
  const asked = new Set((pol.asksFor || []).map((a) => a.iri));
  const assignee = policyAssignee(pol) as Party | null;
  const derived = (pol.version?.derivedFrom || []).filter((d) => !asked.has(d.iri));
  return [
    partyRow(pol, 'field.assigner', PRED.ASSIGNER, pol.assigner, 'edit.hintAssigner'),
    compact && !editLayerActive()
      ? { key: 'field.assignee', value: null, ref: assignee?.iri }
      : partyRow(pol, 'field.assignee', PRED.ASSIGNEE, assignee, 'edit.hintAssignee',
        !assignee || assignee === pol.assignee ? undefined : text('edit.assigneeOfRule')),
    { key: 'field.issued', value: compact ? null : issuedRow(pol) },
    {
      key: 'field.replaces',
      value: pol.version?.revisionOf ? <ProvRef d={pol.version.revisionOf} /> : null,
      ref: pol.version?.revisionOf?.iri,
    },
    { key: 'field.derivedFrom', value: listOrNull(derived, (l) => <ProvRefs list={l} />) },
    { key: 'field.profile', value: profileValue(pol) },
    { key: 'field.reference', value: compact ? null : identifierRow(pol) },
  ];
}

function AccessPoints(props: { pol: Policy }): JSX.Element {
  const urls = () => {
    const ds = datasetOf(props.pol);
    return ds ? (ds.distributions || []).filter((d: any) => d.accessURL) : [];
  };
  return (
    <Show when={urls().length}>
      <div class="servers">
        <TermHeader tag="div" key="head.accessPoints" class="servers-label" />
        <For each={urls()}>{(d: any) => (
          <div class="server-row">
            <Show
              when={safeHref(d.accessURL)}
              fallback={<span class="mono">{d.accessURL}</span>}
            >
              {(h) => <a class="mono" href={h()} target="_blank" rel="noopener">{d.accessURL}</a>}
            </Show>
            <span class="muted">{' — ' + d.label}</span>
          </div>
        )}</For>
      </div>
    </Show>
  );
}

export interface CardBodyProps {
  pol: Policy;
  kind: CardKind;
  compact?: boolean;
  detail?: boolean;
}

export function CardBody(props: CardBodyProps): JSX.Element {
  const rows = (): KvRow[] => {
    if (props.kind === 'offer') return offerRows(props.pol);
    if (props.kind === 'agreement') return agreementRows(props.pol, !!props.detail);
    return setRows(props.pol, !!props.compact);
  };
  const version = () => versionLine(props.pol.version
    ? { ...props.pol.version, revisionOf: null, derivedFrom: [] } : null);
  return (
    <header class="offer-head">
      <Show when={props.pol.curie}>{(c) => <div class="mono muted uid">{c()}</div>}</Show>
      <Show when={props.pol.description || editLayerActive()}>
        <p class="offer-desc">
          <Field spec={{
            term: nodeOf(props.pol),
            kind: 'text',
            preds: PRED.NOTE,
            value: props.pol.description ?? '',
            multiline: true,
            hint: text('edit.hintDescription'),
          }}
          >
            <Show when={props.pol.description}>{(d) => <LongText text={d()} />}</Show>
          </Field>
        </p>
      </Show>
      <Show when={props.compact}><RequestSubtitle pol={props.pol} /></Show>
      <Show when={(props.pol.asksFor || []).length}>
        <p class="ask-line"><AsksFor list={props.pol.asksFor} /></p>
      </Show>
      <Show when={props.kind === 'request'}>
        <p class="answer-line"><DecidedIn iri={props.pol.iri} /></p>
      </Show>
      <Kv rows={rows()} />
      <Show when={props.kind === 'offer'}><AccessPoints pol={props.pol} /></Show>
      <Show when={version()}>{(v) => <p class="version-line muted">{v()}</p>}</Show>
      <Kv rows={extraRows(props.pol.extraProps, nodeOf(props.pol))} />
      <Show when={props.pol.iri}>{(iri) => <BackReferences iri={iri()} />}</Show>
    </header>
  );
}
