import { createMemo, createSignal, For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  compactDate, curie, statusWord, versionNavDate, versionNavModel,
} from '../../model/parse.js';
import { detailNeeded, endpoint, fetchDetail, fetchDetails, model } from '../../stores/corpus.js';
import { text } from '../../stores/view.js';
import type { Policy, Rule } from '../card/card.jsx';
import './version-nav.css';

export interface Version {
  iri: string;
  title?: string;
  curie?: string | null;
  kind?: string | null;
  status?: string;
  stub?: boolean;
  issued?: string | null;
  effectiveFrom?: string | null;
  effectiveTo?: string | null;
  until?: string | null;
  comment?: string | null;
  sources?: string[];
  obligations?: Rule[];
}

interface NavModel {
  container: { iri: string; title: string; validFrom?: string | null; validTo?: string | null };
  versions: Version[];
  index: number;
  total: number;
  complete: boolean;
  shown: Version;
  older: Version | null;
  newer: Version | null;
}

function navModel(iri: string): NavModel | null {
  return versionNavModel(model(), iri) as NavModel | null;
}

function policyAt(iri: string): Policy | null {
  const m = model() as unknown as
    { sets?: Policy[]; offers?: Policy[]; agreements?: Policy[] } | null;
  if (!m || !iri) return null;
  for (const list of [m.sets, m.offers, m.agreements]) {
    const p = (list || []).find((x) => x.iri === iri);
    if (p) return p;
  }
  return null;
}

export function versionTitle(iri: string): string | null {
  const n = navModel(iri);
  return n?.versions.find((v) => v.iri === iri)?.title ?? null;
}

function ownVersion(iri: string): Version {
  const p = policyAt(iri) as (Policy & { version?: { effectiveFrom?: string | null } }) | null;
  return {
    iri,
    issued: (p && p.issued) || null,
    effectiveFrom: (p && p.version && p.version.effectiveFrom) || null,
  };
}

function versionPeriod(v: Version): string {
  return v.status === 'future'
    ? text('vperiod.from', { date: compactDate(v.effectiveFrom) || '?' })
    : text('vperiod.range', {
      from: compactDate(v.effectiveFrom) || '…',
      to: compactDate(v.until) || text('vperiod.present'),
    });
}

function stubSource(v: Version): Policy | null {
  for (const iri of v.sources || []) {
    const p = policyAt(iri);
    if (p) return p;
  }
  return null;
}

export function stubPolicy(v: Version): Policy {
  const source = stubSource(v);
  const period = text('stub.period', {
    from: compactDate(v.effectiveFrom) || '…',
    to: compactDate(v.effectiveTo) || compactDate(v.until) || '…',
  });

  const head = v.status === 'terminated'
    ? text('stub.terminated', { period })
    : text('stub.superseded', { period });
  const b = source as (Policy & { curie?: string | null }) | null;
  return {
    iri: v.iri,
    anon: false,
    stub: true,
    kind: v.kind || 'set',
    curie: v.curie || curie(v.iri),
    title: v.title || v.curie || v.iri,

    description: (b
      ? text('stub.fromSourceLayer', { head, source: b.curie || curie(b.iri) })
      : text('stub.documentOnly', { head }))
      + (v.comment ? '\n\n' + v.comment : ''),
    issued: v.issued || null,
    assigner: b ? b.assigner : null,
    assignee: b ? b.assignee : null,
    profile: null,
    permissions: b ? (b.permissions || []) : [],
    prohibitions: b ? (b.prohibitions || []) : [],

    obligations: (v.obligations && v.obligations.length)
      ? v.obligations : (b ? (b.obligations || []) : []),
    offers: [],
    extraProps: [],
    version: {
      effectiveFrom: v.effectiveFrom || null,
      effectiveTo: v.effectiveTo || null,
      revisionOf: null,
      derivedFrom: (v.sources || []).map((iri) => ({ iri, curie: curie(iri), label: null })),
      supersededBy: [],
    },
  } as Policy;
}

export interface VersionNavProps {

  iri: string;

  onSwitch?: (iri: string) => void;
}

export function VersionNav(props: VersionNavProps): JSX.Element {

  const nm = createMemo(() => navModel(props.iri));
  const shown = (): Version => nm()?.shown ?? ownVersion(props.iri);
  const browsable = () => {
    const n = nm();
    return !!n && (n.total > 1 || !!n.older || !!n.newer);
  };
  const show = () => browsable() || versionNavDate(shown()) !== '—';

  const [busy, setBusy] = createSignal(false);
  const [error, setError] = createSignal('');
  const [menuOpen, setMenuOpen] = createSignal(false);
  const [filled, setFilled] = createSignal(false);

  const known = () => {
    const n = nm();
    return !n || n.complete || !endpoint() || !detailNeeded({ iri: props.iri });
  };
  const older = () => (known() ? (nm()?.older ?? null) : null);
  const newer = () => (known() ? (nm()?.newer ?? null) : null);
  const total = () => nm()?.total ?? 1;

  const openEnded = () => !known() && total() > 1;

  const report = (e: unknown) => {
    setError(text('vnav.loadFailed', { msg: e instanceof Error ? e.message : String(e) }));
  };

  const go = async (v: Version | null) => {
    if (!v || busy()) return;
    setBusy(true);
    setError('');
    try {

      if (endpoint()) {
        const targets = v.stub
          ? (v.sources || []).filter((iri) => !/publicaties\.rvig\.nl|\.pdf$/i.test(iri))
          : [v.iri];

        await fetchDetails(targets.filter((iri) => detailNeeded({ iri })));
      }
      props.onSwitch?.(v.iri);
    } catch (e) {
      report(e);
    } finally {
      setBusy(false);
    }
  };

  const resolve = async (back: boolean) => {
    if (busy()) return;
    setBusy(true);
    setError('');
    let v: Version | null = null;
    try {
      if (endpoint() && detailNeeded({ iri: props.iri })) await fetchDetail(props.iri);
      const nav = navModel(props.iri);
      v = (nav && (back ? nav.older : nav.newer)) || null;
      if (!v) props.onSwitch?.(props.iri);
    } catch (e) {
      report(e);
      setBusy(false);
      return;
    }
    setBusy(false);
    if (v) await go(v);
  };

  const stop = (e: Event) => { e.stopPropagation(); e.preventDefault(); };

  // A disabled <button> and not a hidden span: an invisible span lets the click
  // fall through to the <summary> and toggles the card.
  const Arrow = (p: { version: Version | null; back: boolean }): JSX.Element => {
    const live = () => !!p.version || openEnded();
    const label = () => (p.version
      ? text(p.back ? 'vnav.olderDated' : 'vnav.newerDated',
        { date: versionNavDate(p.version) })
      : (live() ? text(p.back ? 'vnav.older' : 'vnav.newer') : ''));
    return (
      <button
        type="button"
        class={'vnav-arrow' + (live() ? '' : ' vnav-arrow-off')}
        title={label() || undefined}
        aria-label={label() || undefined}
        disabled={!live()}
        aria-hidden={live() ? undefined : 'true'}
        tabindex={live() ? undefined : -1}
        onClick={(e) => {
          stop(e);
          if (p.version) void go(p.version); else void resolve(p.back);
        }}
      >
        {p.back ? '‹' : '›'}
      </button>
    );
  };

  const menuLabel = () => text('vnav.allVersions', { n: total() });

  const versions = () => (filled() ? [...(nm()?.versions || [])].reverse() : []);

  const openMenu = async () => {
    if (!filled()) {

      if (!known() && endpoint() && detailNeeded({ iri: props.iri })) {
        setBusy(true);
        try { await fetchDetail(props.iri); } catch { }
        setBusy(false);
      }
      setFilled(true);
    }
    setMenuOpen(!menuOpen());

    if (menuOpen() && typeof document !== 'undefined') {
      document.addEventListener('click', () => setMenuOpen(false), { once: true });
    }
  };

  return (
    <Show when={show()}>
      <span
        class="vnav-wrap"
        onClick={stop}
        onPointerDown={(e) => e.stopPropagation()}
      >
        <span class={busy() ? 'vnav busy' : 'vnav'}>
          <Arrow version={older()} back />
                    <Show
            when={total() > 1}
            fallback={(
              <span class="vnav-date mono" title={text('vnav.versionDate')}>
                {versionNavDate(shown())}
              </span>
            )}
          >
            <button
              type="button"
              class="vnav-date mono"
              title={menuLabel()}
              aria-label={text('vnav.versionAria', {
                date: versionNavDate(shown()), menu: menuLabel(),
              })}
              aria-haspopup="true"
              aria-expanded={menuOpen()}
              onClick={(e) => { stop(e); void openMenu(); }}
            >
              {versionNavDate(shown())}
            </button>
          </Show>
          <Arrow version={newer()} back={false} />
        </span>
        <Show when={total() > 1}>
          <div class="vnav-menu" hidden={!menuOpen()}>
            <Show when={filled() && nm()}>{(n) => (
              <>
                <div class="vnav-menu-head muted">{text('vnav.allVersions', {
                  n: n().versions.length,
                })}</div>
                <div class="vnav-menu-sub muted">
                  {n().container.title
                    + ((n().container.validFrom || n().container.validTo)
                      ? text('vnav.validity', {
                        from: compactDate(n().container.validFrom) || '…',
                        to: compactDate(n().container.validTo) || '…',
                      }) : '')}
                </div>
              </>
            )}</Show>
            <For each={versions()}>{(v) => {
              const isShown = () => v.iri === props.iri;
              return (
                <button
                  type="button"
                  class={'vnav-mi' + (isShown() ? ' shown' : '')}
                  title={versionPeriod(v)}
                  aria-current={isShown() ? 'true' : undefined}
                  onClick={(e) => {
                    stop(e);
                    setMenuOpen(false);
                    if (!isShown()) void go(v);
                  }}
                >
                  <span class="vnav-mi-date mono">{versionNavDate(v)}</span>
                  <span class={'vchip ' + (v.status || '')}>{statusWord(v.status)}</span>
                  <span class="vnav-mi-title">{v.title}</span>
                </button>
              );
            }}</For>
          </div>
        </Show>
        <Show when={error()}><span class="src-err">{error()}</span></Show>
      </span>
    </Show>
  );
}
