import { text } from '../../stores/view.js';

export interface FilterProps {

  query: string;
  setQuery: (q: string) => void;

  shown: number;
  total: number;

  ref?: (el: HTMLInputElement) => void;
}

export function Filter(props: FilterProps) {
  const count = () => (props.query.trim()
    ? text('count.ofTotal', { n: props.shown, total: props.total })
    : '');
  return (
    <div class="tree-filter-row">
      <input
        type="search"
        class="tree-filter"
        value={props.query}
        placeholder={text('tree.filterPlaceholder')}
        aria-label={text('tree.filterAria')}
        ref={(el) => props.ref?.(el)}
        onInput={(e) => props.setQuery(e.currentTarget.value || '')}
      />
      <span class="tree-count" aria-live="polite">{count()}</span>
    </div>
  );
}
