import { createMemo, createSignal, For, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { groupRules, pivotDimensions } from '../../model/parse.js';
import { model } from '../../stores/corpus.js';
import { text, view, setView } from '../../stores/view.js';
import type { Rule } from '../card/card.jsx';
import './list.css';

export interface Dimension {
  iri: string;
  curie?: string | null;
  label?: string | null;
  order?: number | null;
}

export type GroupNode =
  | { kind: 'rule'; rule: Rule; label: string | null }
  | {
    kind: 'group';
    dim: Dimension;
    value: { iri?: string | null; curie?: string | null; label?: string };
    rules: Rule[];
    children: GroupNode[];
  };

function declarations(): Dimension[] {
  const m = model() as { groupingDimensions?: Dimension[] } | null;
  return (m && m.groupingDimensions) || [];
}

export function declaredDimensions(): Dimension[] {
  return pivotDimensions(declarations(), null) as Dimension[];
}

export function activeDimensions(): Dimension[] {
  return pivotDimensions(declarations(), view.groupBy) as Dimension[];
}

export function groupingDiffers(): boolean {
  const decl = declaredDimensions();
  const act = activeDimensions();
  return decl.length !== act.length || decl.some((d, i) => d.iri !== act[i].iri);
}

export function setGrouping(dims: Dimension[]): void {
  const decl = declaredDimensions();
  const same = decl.length === dims.length && decl.every((d, i) => d.iri === dims[i].iri);
  setView({ groupBy: same ? null : dims.map((d) => d.curie || d.iri) });
}

export function removeDimension(dim: Dimension): void {
  setGrouping(activeDimensions().filter((d) => d.iri !== dim.iri));
}

export function addDimension(dim: Dimension): void {
  const active = activeDimensions();
  if (active.some((d) => d.iri === dim.iri)) return;
  setGrouping([...active, dim]);
}

export function restoreGrouping(): void {
  setView({ groupBy: null });
}

const [openMenu, setOpenMenu] = createSignal<symbol | null>(null);
let openBox: HTMLElement | null = null;

export function closeDimMenu(): boolean {
  if (openMenu() === null) return false;
  setOpenMenu(null);
  openBox = null;
  return true;
}

if (typeof document !== 'undefined' && document.addEventListener) {

  document.addEventListener('click', (e) => {
    if (openMenu() === null) return;
    const target = e.target as Node | null;
    if (openBox && target && openBox.contains(target)) return;
    closeDimMenu();
  }, true);
}

function name(d: Dimension): string {
  return d.label || d.curie || d.iri;
}

function Dimchip(props: { dim: Dimension }): JSX.Element {
  const label = () => name(props.dim);
  const title = () => text('pivot.remove', { label: label() });
  return (
    <span class="sec-filter-dim">
      <span class="sec-filter-dim-lab">{label()}</span>
      <button
        type="button"
        class="sec-filter-dim-x"
        title={title()}
        aria-label={title()}
        onClick={(e) => {
          e.preventDefault();
          closeDimMenu();
          removeDimension(props.dim);
        }}
      >
        ×
      </button>
    </span>
  );
}

function AddChip(props: { rest: Dimension[] }): JSX.Element {
  const token = Symbol('dimension menu');
  const open = () => openMenu() === token;
  let box!: HTMLSpanElement;
  return (
    <span class="sec-filter-dim-wrap" ref={box}>
      <button
        type="button"
        class="sec-filter-dim-add"
        title={text('pivot.add')}
        aria-label={text('pivot.add')}
        aria-expanded={open()}
        aria-haspopup="menu"
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          if (props.rest.length === 1) {
            closeDimMenu();
            addDimension(props.rest[0]);
            return;
          }
          const was = open();
          closeDimMenu();
          if (was) return;
          openBox = box;
          setOpenMenu(token);
        }}
      >
        +
      </button>
      <Show when={props.rest.length > 1}>
        <div class="sec-filter-dim-menu" role="menu" hidden={!open()}>
          <For each={props.rest}>{(d) => (
            <button
              type="button"
              class="sec-filter-dim-opt"
              role="menuitem"
              title={text('pivot.addItem', { label: name(d) })}
              aria-label={text('pivot.addItem', { label: name(d) })}
              onClick={(e) => {
                e.preventDefault();
                closeDimMenu();
                addDimension(d);
              }}
            >
              {name(d)}
            </button>
          )}</For>
        </div>
      </Show>
    </span>
  );
}

export function GroupingPath(): JSX.Element {
  const all = createMemo(declaredDimensions);
  const active = createMemo(activeDimensions);
  const rest = createMemo(() => all().filter((d) => !active().some((a) => a.iri === d.iri)));
  return (
    <Show when={all().length}>
      <div class="sec-filter-item">
        <span class="sec-filter-lab">{text('pivot.label')}</span>
        <div class="sec-filter-pivot">
          <For each={active()}>{(d, i) => (
            <>
              <Show when={i()}>
                <span class="sec-filter-sep" aria-hidden="true">›</span>
              </Show>
              <Dimchip dim={d} />
            </>
          )}</For>
          <Show when={rest().length}><AddChip rest={rest()} /></Show>
        </div>
      </div>
    </Show>
  );
}

export function groupBy(rules: Rule[]): GroupNode[] {
  return groupRules(rules, activeDimensions()) as GroupNode[];
}
