import { createEffect, createRoot, createSignal, For, onCleanup, onMount, Show } from 'solid-js';
import { Dynamic } from 'solid-js/web';
import type { JSX } from 'solid-js';
import { text, view, setNotice, setView } from '../../stores/view.js';
import { graph, loadStatus } from '../../stores/corpus.js';
import { editSource, sourceRows, recoveryBusy, makeEditable } from '../../stores/source-management.js';
import type { SourceEdit } from '../../stores/source-management.js';
import { sourcesOpen, setSourcesOpen } from './sources.jsx';
import { refusalReason, refusalReasonKey } from './source-actions.jsx';
import { sourceChoice, setSourceChoice } from '../edit/hooks.jsx';

export interface EditLayer {

  Chrome: () => JSX.Element;

  setEditMode: (on: boolean, options?: { confirm?: boolean }) => boolean;
}

const [layer, setLayer] = createSignal<EditLayer | null>(null);

const [sourcePickerOpen, setPickerOpen] = createSignal(false);
const [loading, setLoading] = createSignal(false);
const [failed, setFailed] = createSignal(false);

export const sourcePanelEdited = (): boolean => view.editMode || sourceChoice();

export { sourcePickerOpen, layer, failed };

function openPicker(): void { setPickerOpen(true); }

let load: Promise<EditLayer | null> | null = null;

// The only dynamic import of the edit layer. This file sits in the read chunk,
// so nothing here may import it statically.
export function loadEditLayer(): Promise<EditLayer | null> {
  if (load) return load;
  setLoading(true);
  load = import('../edit/layer.jsx')
    .then((mod) => mod.load())
    .then((l: EditLayer) => {
      setLayer(() => l);
      setFailed(false);
      return l;
    })
    .catch((e: unknown) => {

      load = null;
      setFailed(true);
      setNotice('edit.loadFailed', {
        error: e instanceof Error ? e.message : String(e),
      });
      return null;
    })
    .finally(() => setLoading(false));
  return load;
}

export function _restoreForTest(): void {
  load = null;
  setLayer(null);
  setLoading(false);
  setFailed(false);
  setSourceChoice(false);

  setPickerOpen(false);
}

export async function toggleEditState(on?: boolean): Promise<boolean> {
  const want = on === undefined ? !view.editMode : !!on;
  if (!want) {
    const l = layer();
    if (l) l.setEditMode(false);

    else setView({ editMode: false });
    return false;
  }

  if (!editSource()) {
    const list = selectableSources();
    if (list.length > 1) { openPicker(); return false; }
    if (list.length === 1) await makeEditable(list[0]);
    else {

      const reason = noEditSourceReason();
      if (reason) { setNotice(reason); return false; }
    }
  }
  const l = await loadEditLayer();
  if (!l) return false;
  const ok = l.setEditMode(true);

  if (!ok && !sourcesOpen()) setSourcesOpen(true);
  return ok;
}

function sourcesSettled(): boolean {
  if (recoveryBusy()) return false;
  const state = loadStatus();
  if (state === 'loading') return false;
  return state !== 'ready' || !!graph();
}

function awaitSources(): Promise<void> {
  if (sourcesSettled()) return Promise.resolve();
  return new Promise((done) => {
    createRoot((cleanup) => {
      let fired = false;
      createEffect(() => {
        if (fired || !sourcesSettled()) return;
        fired = true;

        queueMicrotask(cleanup);
        done();
      });
    });
  });
}

export async function startEditDeeplink(): Promise<void> {
  await awaitSources();

  if (!view.editMode) return;

  if (!editSource()) {

    const list = selectableSources();
    if (list.length) await makeEditable(list[0]);
  }

  if (!editSource() && loadStatus() === 'error') {
    if (view.editMode) setView({ editMode: false });
    return;
  }
  const l = await loadEditLayer();

  if (l) l.setEditMode(true);
}

export function noEditSourceReason(): string | null {
  const candidates = sourceRows().filter((b) => !b.fromSparql && !b.vocab);
  if (!candidates.length) return null;
  const grounds = candidates.map((b) => refusalReasonKey(b));
  if (grounds.some((g) => g === null)) return null;
  return grounds.includes('src.opfsOff') ? 'src.opfsOff' : grounds[0];
}

export function selectableSources(): SourceEdit[] {

  return sourceRows().filter((b) => !b.fromSparql && !b.vocab && !refusalReason(b));
}

export function EditButton(): JSX.Element {
  return (
    <button
      class="btn edit-mode-button"
      id="btn-edit"
      type="button"
      aria-pressed={view.editMode ? 'true' : 'false'}

      aria-busy={loading() ? 'true' : undefined}
      title={text(view.editMode ? 'edit.off' : 'edit.on')}

      aria-label={text('edit.card')}
      onClick={() => { void toggleEditState(); }}
    >✎</button>
  );
}

function SourcePicker(): JSX.Element {
  let box: HTMLDivElement | undefined;
  const focusable = (): HTMLElement[] =>
    [...(box?.querySelectorAll<HTMLElement>('button:not([disabled])') ?? [])];

  const close = (): void => {
    setPickerOpen(false);
    if (typeof document !== 'undefined') {
      (document.getElementById('btn-edit') as HTMLElement | null)?.focus();
    }
  };
  const choose = (b: SourceEdit): void => {
    setPickerOpen(false);
    void makeEditable(b).then(() => toggleEditState(true));
  };

  onMount(() => {
    if (typeof document === 'undefined') return;
    document.body.classList.add('source-picker-open');
    focusable()[0]?.focus();
    const onKey = (e: KeyboardEvent): void => {
      if (e.key === 'Escape') {
        e.preventDefault();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();
        else e.stopPropagation();
        close();
        return;
      }
      if (e.key !== 'Tab') return;
      const l = focusable();
      if (!l.length) return;
      const here = l.indexOf(document.activeElement as HTMLElement);
      const target = e.shiftKey
        ? (here <= 0 ? l.length - 1 : here - 1)
        : (here === l.length - 1 ? 0 : here + 1);
      e.preventDefault();
      l[target].focus();
    };
    document.addEventListener('keydown', onKey, true);
    onCleanup(() => {
      document.removeEventListener('keydown', onKey, true);
      document.body.classList.remove('source-picker-open');
    });
  });

  return (
    <div class="source-picker-screen">
      <div
        class="source-picker"
        id="source-picker"
        role="dialog"
        aria-modal="true"
        aria-labelledby="source-picker-title"
        ref={box}
      >
        <h2 class="source-picker-title" id="source-picker-title">{text('edit.chooseSource')}</h2>
        <p class="source-picker-note muted">{text('src.editSourcePanel')}</p>
        <ul class="source-picker-list">
          <For each={selectableSources()}>{(b) => (
            <li>
              <button
                type="button"
                class="source-picker-choice"
                title={b.opfs
                  ? text('edit.chooseSourceShort')
                  : `${text('edit.chooseSourceShort')} — ${text('src.lockWarning')}`}
                onClick={() => choose(b)}
              >{b.name}</button>
            </li>
          )}</For>
        </ul>
        <button
          type="button"
          class="btn source-picker-cancel"
          onClick={() => close()}
        >{text('src.lockCancel')}</button>
      </div>
    </div>
  );
}

export function EditChrome(): JSX.Element {
  onMount(() => {

    if (view.editMode) void startEditDeeplink();
  });

  createEffect(() => {
    const b = typeof document === 'undefined' ? null : document.body;
    if (!b) return;
    b.classList.toggle('edit-mode', view.editMode);
    b.classList.toggle('edit-mode-failed-load', failed());
  });

  return (
    <>
      <Show when={sourcePickerOpen()}><SourcePicker /></Show>
      <Show when={layer()}>{(l) => <Dynamic component={l().Chrome} />}</Show>
    </>
  );
}
