const ODRL_ACTION = 'http://www.w3.org/ns/odrl/2/action';

export function rowKey(rule: Rule, scope?: string | null): string {
  const t = (rule as { term?: { id?: string; value?: string } | null }).term;
  const id = rule.iri || (t && (t.id || t.value)) || '';
  return id ? `row:${scope || ''}|${id}` : '';
}

function action(rule: Rule): RuleAction | null {
  if (!rule.action) return null;
  return typeof rule.action === 'string' ? { label: rule.action } : rule.action;
}

function actionTitle(rule: Rule): string | null {
  const a = action(rule);
  if (!a || !a.label) return null;
  const tg = rule.targets || [];
  return tg.length === 1 && tg[0].label ? `${a.label} · ${tg[0].label}` : a.label;
}

const FALLBACK_KEY: Record<string, string> = {
  permission: 'title.permission', prohibition: 'title.prohibition', duty: 'title.duty',
};

export function ruleTitle(rule: Rule, kind: RuleKind, name?: string | null): string {
  const own = kind === 'duty' ? rule.label : rule.title;
  return own || name || actionTitle(rule)
    || text(FALLBACK_KEY[kind] || 'title.permission');
}

function dutyParams(rule: Rule, withoutAction = false): string {
  const parts: string[] = [];
  const a = action(rule);
  if (!withoutAction && a && a.label && a.label !== rule.label) parts.push(a.label);
  if (rule.informedParty) {
    parts.push(text('duty.inform', {
      party: rule.informedParty.label || rule.informedParty.curie,
    }));
  }
  return parts.join(' · ');
}

function actionRow(rule: Rule, a: RuleAction | null, title: string): KvRow | null {
  const readNode = a && a.label ? (
    <span data-iri={a.iri || undefined}>
      {a.label}
    </span>
  ) : null;
  const visibleInRead = !!readNode && a!.label !== title;
  if (!editLayerActive()) {
    return { key: 'field.action', value: visibleInRead ? readNode : null, ref: a?.iri };
  }
  const term = (rule as { term?: unknown }).term ?? rule.iri;
  if (!term) return { key: 'field.action', value: visibleInRead ? readNode : null, ref: a?.iri };
  return {
    key: 'field.action',
    ref: a?.iri,
    value: (
      <Field spec={{
        term,
        kind: 'iri',
        preds: [ODRL_ACTION],
        iri: a?.iri ?? null,
        hint: text('edit.hintAction'),
        value: a?.label ?? null,
        category: 'actions',
        variant: 'action',
      }}
      >{readNode}</Field>
    ),
  };
}

function assigneeRow(rule: Rule, ownAssignee: Party | null): KvRow {
  const term = (rule as { term?: unknown }).term ?? rule.iri;
  if (!editLayerActive() || !term) {
    return {
      key: 'field.assignee',
      value: ownAssignee ? <Ref agent={ownAssignee} /> : null,
      ref: ownAssignee?.iri,
    };
  }
  const readNode = rule.assignee ? <Ref agent={rule.assignee} /> : null;
  return {
    key: 'field.assignee',
    ref: rule.assignee?.iri,
    value: (
      <Field spec={{
        term,
        kind: 'iri',
        preds: PRED.ASSIGNEE,
        iri: rule.assignee?.iri ?? null,
        category: 'parties',
        hint: text('edit.hintAssignee'),
        newGroup: true,
      }}
      >{readNode}</Field>
    ),
  };
}

function TargetTag(props: {
  tg: { label?: string | null; term?: unknown }; iri: string | null; rule: Rule;
}): JSX.Element {
  return (
    <span class="target-tag" title={props.iri || undefined} data-iri={props.iri || undefined}>
      <Field spec={{
        term: props.iri || (props.tg as { term?: unknown }).term,
        kind: 'text',
        preds: PRED.TITLE,
        value: props.tg.label ?? '',
      }}
      >{props.tg.label}</Field>
      <Hook name="targetCross" ctx={{ rule: props.rule, iri: props.iri }} />
    </span>
  );
}

function ruleRows(
  rule: Rule, kind: RuleKind, owner?: Party | null,
  name?: string | null, scope?: string | null,
): KvRow[] {
  const ownTitle = ruleTitle(rule, kind, name);
  if (kind === 'duty') {
    const row = editLayerActive() ? actionRow(rule, action(rule), ownTitle) : null;
    return row ? [row] : [];
  }
  const title = ownTitle;
  const a = action(rule);
  const ownAssignee = rule.assignee
    && (!owner || rule.assignee.iri !== owner.iri) ? rule.assignee : null;
  return [
    assigneeRow(rule, ownAssignee),
    actionRow(rule, a, title) as KvRow,
    {
      key: 'field.target',
      value: ((rule.targets || []).length || editLayerActive()) ? (
        <span class="targets">
          <NodeChain.Provider value={[`${rowKey(rule, scope)}#target`]}>
          <For each={rule.targets}>{(tg) => (
            <>

              <Show
                when={isCollection(tg as CollectionNode)}
                fallback={(
                  <NodeFold iri={tg.iri || null}>
                    <TargetTag tg={tg} iri={tg.iri || null} rule={rule} />
                  </NodeFold>
                )}
              >
                <Collection
                  desc={tg as CollectionNode}
                  tag={(iri) => <TargetTag tg={tg} iri={iri} rule={rule} />}
                />
              </Show>
            </>
          )}</For>
          </NodeChain.Provider>
          <Hook name="targetGhost" ctx={{ rule: rule }} />
        </span>
      ) : null,
    },
    {
      key: 'field.sourceLocation',
      value: (rule.primarySources || []).length
        ? <ProvRefs list={rule.primarySources} cls="src-loc" /> : null,
    },
  ];
}

export interface RuleRowProps {
  rule: Rule;
  kind: RuleKind;
  owner?: Party | null;
  mark?: string | null;
  scope?: string | null;
  name?: string | null;
  shownDims?: string[];
  parent?: unknown;
}

export function RuleRow(props: RuleRowProps): JSX.Element {
  const title = () => ruleTitle(props.rule, props.kind, props.name);
  const key = () => rowKey(props.rule, props.scope);
  const rows = () => ruleRows(
    props.rule, props.kind, props.owner, props.name, props.scope,
  );
  const params = () => (props.kind === 'duty'
    ? dutyParams(props.rule, editLayerActive()) : '');
  const allParams = () => (props.kind === 'duty' ? dutyParams(props.rule) : '');
  const noParams = () => props.kind === 'duty' && !allParams()
    && !(props.rule.constraints || []).length && !(props.rule.refinements || []).length
    && !(props.rule.duties || []).length;
  const node = () => props.rule.iri || (props.rule as { term?: unknown }).term;
  const extra = () => extraRows(
    props.rule.extraProps, node(), rowKey(props.rule, props.scope),
  );
  const coverage = () => (props.rule as { coverage?: Coverage | null }).coverage;
  const inCoverageContext = () => !!coverage()?.inConformsContext;
  const organisational = () => inCoverageContext() && !!coverage()?.organisational;
  const hasNextStep = () => (coverageNext(props.rule) as { targetRef?: string }[])
    .some((x) => x && x.targetRef);
  const showsGear = () => !!props.rule.iri && inCoverageContext()
    && !organisational() && hasNextStep();
  const row: RowBuilder = (r, kind, mark) => (
    <RuleRow
      rule={r} kind={kind} mark={mark}
      owner={props.owner} scope={props.scope}
      parent={props.rule}
    />
  );
  const constraints = createMemo(() => constraintList(props.rule, props.shownDims));
  const sections = () => !!constraints().length
    || !!(props.rule.duties || []).length
    || !!((props.rule as { consequences?: unknown[] }).consequences || []).length
    || editLayerActive();
  const hasContent = () => !!props.rule.description || !!params() || noParams()
    || !!extra().length || sections() || rows().some((r) => r.value != null && r.value !== '');
  return (
    <details
      class={'op-row ' + props.kind + (hasContent() ? '' : ' op-leaf') + ghostRevealClass()}
      data-iri={props.rule.iri || undefined}
      data-ref={props.rule.iri || undefined}
      open={isRowOpen(key())}
      onToggle={(e) => setRowOpen(key(), e.currentTarget.open)}
    >
      <summary class="op-summary" {...headerControls()}>
        <RuleBadge kind={props.kind} />
        <ChipSpace />
        <span class="op-title" title={title()}>

          <span class="op-name">
            <Field spec={{
              term: props.rule.iri || (props.rule as { term?: unknown }).term,
              kind: 'text',
              preds: PRED.TITLE,
              value: title(),
              hint: text('edit.hintName'),
              focusKey: focusAddress((props.rule as { term?: unknown }).term
                ?? props.rule.iri),
            }}
            >{title()}</Field>
          </span>
          <Show when={!props.rule.iri && (props.rule as { term?: unknown }).term}>
            <Field spec={{
              term: (props.rule as { term?: unknown }).term,
              kind: 'iri',
              preds: [],
              variant: 'nodeIri',
              iri: null,
            }}
            />
          </Show>
          <Show when={props.mark}>{(m) => (
            <><ChipSpace /><span class="op-path muted">{m()}</span></>
          )}</Show>
        </span>
        <Show when={organisational()}>
          <ChipSpace />
          <span class="cov-organisational muted" title={text('cov.organisationalRuleTitle')}>
            {text('cov.organisational')}
          </span>
        </Show>
        <Show when={showsGear()}>
          <ChipSpace />
          <FillButton target={props.rule.iri!} scope={props.scope ?? null} />
        </Show>
        <ChipSpace />
        <Hook
          name="ruleStrip"
          ctx={{
            rule: props.rule, kind: props.kind, parent: props.parent,
            scope: props.scope ?? null,
          }}
        />
        <Chevron />
      </summary>
      <Show when={hasContent()}>
        <div class="op-body">
          <Show when={props.rule.description}>{(d) => (
            <p class="rule-desc"><LongText text={d()} /></p>
          )}</Show>
          <Show when={params()}>{(s) => <p class="duty-sub">{s()}</p>}</Show>
          <Show when={noParams()}>
            <p class="duty-sub muted">{text('duty.noParams')}</p>
          </Show>
          <Kv rows={rows()} />
          <Constraints
            rule={props.rule}
            scope={props.scope}
            shownDims={props.shownDims}
          />
          <Duties rule={props.rule} row={row} kind={props.kind} />
          <Consequences rule={props.rule} row={row} />
          <Show when={extra().length}>
            <h4>{text('head.otherProps')}</h4>
            <Kv rows={extra()} />
          </Show>
        </div>
      </Show>
    </details>
  );
}

const NOUN_KEY: Record<string, string> = {
  permission: 'noun.permission', prohibition: 'noun.prohibition', duty: 'noun.duty',
};

export function groupCount(rules: Rule[], kind: RuleKind): string {
  const kinds = new Set(rules.map((r) => (r.kind === 'duty' ? 'duty' : kind)));
  return kinds.size === 1
    ? text(NOUN_KEY[[...kinds][0]] || 'rules.count', { n: rules.length })
    : text('rules.count', { n: rules.length });
}

export function RuleNode(props: {
  node: GroupNode;
  kind: RuleKind;
  owner?: Party | null;
  scope?: string | null;
  shownDims: string[];
  parent?: unknown;
}): JSX.Element {
  return (
    <Show
      when={props.node.kind === 'group' ? props.node : null}
      fallback={(
        <RuleRow
          rule={(props.node as { rule: Rule }).rule}
          kind={props.kind}
          owner={props.owner}
          scope={props.scope}
          name={(props.node as { label: string | null }).label}
          shownDims={props.shownDims}
          parent={props.parent}
        />
      )}
    >{(group) => {
      const deeper = () => [...props.shownDims, group().dim.iri];
      const groupKey = () => {
        const w = group().value.iri || group().value.label || '';
        return w ? `group:${props.scope || ''}|${group().dim.iri}|${w}` : '';
      };
      const curie = () => {
        const c = group().value.curie;
        return c && !/^https?:/.test(c) ? c : null;
      };
      const valueNode = () => {
        const i = group().value.iri;
        return i && /^[a-z][a-z0-9+.-]*:/i.test(i) ? i : null;
      };
      return (
        <details
          class={'op-row ' + props.kind + ' level' + ghostRevealClass()}
          data-iri={group().value.iri || undefined}
          open={isRowOpen(groupKey())}
          onToggle={(e) => {
            setRowOpen(groupKey(), e.currentTarget.open);
            if (e.currentTarget.open) scrollSyncAfterExpand(e.currentTarget);
          }}
        >
          <summary class="op-summary" {...headerControls()}>
            <span class={'method ' + props.kind}>{group().dim.label || group().dim.iri}</span>
            <ChipSpace />
            <span class="op-title" title={group().value.label}>

              <span class="op-name">
                <Field spec={{
                  term: valueNode(),
                  kind: 'text',
                  preds: PRED.NAME,
                  value: group().value.label ?? '',
                  hint: text('edit.hintName'),
                  label: group().dim.label || group().dim.iri,
                  notApplicable: valueNode() ? undefined : text('edit.groupValueNoNode'),
                }}
                >{group().value.label}</Field>
              </span>
              <Show when={curie()}>{(c) => (
                <><ChipSpace /><span class="op-path mono muted">{c()}</span></>
              )}</Show>
            </span>
            <ChipSpace />
            <span class="op-sum muted">{groupCount(group().rules, props.kind)}</span>
            <ChipSpace />
            <Hook
              name="ruleStrip"
              ctx={{
                rule: { iri: null } as Rule, kind: props.kind, derived: true,
                scope: props.scope ?? null,
              }}
            />
            <Chevron />
          </summary>
          <div class="op-body">
            <div class="op-list">
              <For each={group().children}>{(kind) => (
                <RuleNode
                  node={kind}
                  kind={props.kind}
                  owner={props.owner}
                  scope={props.scope}
                  shownDims={deeper()}
                  parent={props.parent}
                />
              )}</For>
              <Show when={!group().children.some((k) => k.kind === 'group')}>
                <Hook
                  name="groupGhost"
                  ctx={{
                    pol: props.parent as Policy,
                    kind: props.kind,
                    dimIri: group().dim.iri,
                    valueIri: group().value.iri ?? null,
                    valueLabel: group().value.label ?? null,
                  }}
                />
              </Show>
            </div>
          </div>
        </details>
      );
    }}</Show>
  );
}

export function ruleList(pol: Policy): { rule: Rule; kind: RuleKind }[] {
  return [
    ...(pol.obligations || []).map((r) => ({ rule: r, kind: 'duty' as RuleKind })),
    ...(pol.permissions || []).map((r) => ({ rule: r, kind: 'permission' as RuleKind })),
    ...(pol.prohibitions || []).map((r) => ({ rule: r, kind: 'prohibition' as RuleKind })),
  ];
}

export function Rules(props: {
  pol: Policy; kind?: CardKind; owner?: Party | null;
}): JSX.Element {
  const rows = () => ruleList(props.pol);
  const owner = () => {
    if (props.owner !== undefined) return props.owner;
    return props.kind === 'offer' ? null : (policyAssignee(props.pol) as Party | null);
  };
  const row: RowBuilder = (r, kind, mark) => (
    <RuleRow
      rule={r} kind={kind} mark={mark} owner={owner()} scope={props.pol.iri}
      parent={props.pol}
    />
  );
  const sections = createMemo(() => offerSections(props.pol));
  const nodesOfKind = (kind: RuleKind) => {
    void activeDimensions();
    return groupBy(ownRules(props.pol)
      .filter((r) => r.kind === kind).map((r) => r.rule));
  };
  const permissionNodes = createMemo(() => (sections() ? [] : nodesOfKind('permission')));
  const prohibitionNodes = createMemo(() => nodesOfKind('prohibition'));
  const duties = createMemo(() => ownDuties(props.pol));

  const hasSection = (s: RuleKind): boolean => {
    if (s === 'duty') return duties().rules.length > 0;
    if (s === 'permission') {
      return sections() ? (sections() as unknown[]).length > 0 : permissionNodes().length > 0;
    }
    return prohibitionNodes().length > 0;
  };
  const sectionGhost = (s: RuleKind): JSX.Element => (
    <Hook
      name="cardGhost"
      ctx={{ pol: props.pol, kind: props.kind, kinds: [s], placement: 'section' }}
    />
  );
  const SectionHeader = (p: { kind: RuleKind; termKey: string }): JSX.Element => (
    <TermHeader tag="h3" key={p.termKey} class={`rules-subheader ${p.kind}`} />
  );
  const withoutSection = createMemo(
    () => (['duty', 'permission', 'prohibition'] as RuleKind[]).filter((s) => !hasSection(s)),
  );
  return (
    <Show when={showsRules(props.pol) || editLayerActive()}>
      <InheritedFold pol={props.pol} row={row} />
      <OfferFold pol={props.pol} row={row} />

      <Show when={hasSection('duty')}>
        <SectionHeader kind="duty" termKey="head.obligations" />
        <div class="op-list">
          <For each={duties().rules}>{(d) => (
            row(d, 'duty', duties().additional ? text('offerRules.extra') : null)
          )}</For>
          {sectionGhost('duty')}
        </div>
      </Show>

      <Show when={hasSection('permission')}>
        <SectionHeader kind="permission" termKey="head.permissions" />
        <div class="op-list">
          <For each={sections() || []}>{(sec) => (
            <>
              <div class="agr-offer-sec">
                <Show when={sec.offer} fallback={text('agr.otherPermissions')}>{(off) => (
                  <>{text('agr.onOffer')}<span class="offer-name">{off().title}</span></>
                )}</Show>
              </div>
              <For each={groupBy(sec.rules)}>{(node) => (
                <RuleNode
                  node={node}
                  kind="permission"
                  owner={owner()}
                  scope={props.pol.iri}
                  shownDims={[]}
                  parent={props.pol}
                />
              )}</For>
            </>
          )}</For>
          <For each={permissionNodes()}>{(node) => (
            <RuleNode
              node={node}
              kind="permission"
              owner={owner()}
              scope={props.pol.iri}
              shownDims={[]}
              parent={props.pol}
            />
          )}</For>
          {sectionGhost('permission')}
        </div>
      </Show>

      <Show when={hasSection('prohibition')}>
        <SectionHeader kind="prohibition" termKey="head.prohibitions" />
        <div class="op-list">
          <For each={prohibitionNodes()}>{(node) => (
            <RuleNode
              node={node}
              kind="prohibition"
              owner={owner()}
              scope={props.pol.iri}
              shownDims={[]}
              parent={props.pol}
            />
          )}</For>
          {sectionGhost('prohibition')}
        </div>
      </Show>

      <Show when={withoutSection().length && editLayerActive()}>
        <div class="op-list">
          <Hook
            name="cardGhost"
            ctx={{
              pol: props.pol,
              kind: props.kind,
              kinds: withoutSection(),
              placement: 'collect',
            }}
          />
        </div>
      </Show>
      <Show when={props.kind === 'offer'}>
        <Hook name="agreementGhost" ctx={{ pol: props.pol, kind: props.kind }} />
      </Show>
    </Show>
  );
}
