import {
  createEffect, createMemo, createResource, createRoot, createSignal, For, on, onCleanup,
  Show,
} from 'solid-js';
import type { JSX } from 'solid-js';
import {
  cardChunk, CARD_CHUNK_SIZE, filterIndexRows,
  partyLabel, policyAssignee, policyLifecycle, refListCollapsed, setIndexRows,
} from '../../model/parse.js';
import { detailNeeded, fetchDetail, listPhase, model } from '../../stores/corpus.js';
import { corpusKey, isOpen, setOpen } from '../../stores/open-state.js';
import { registerRevealer, text, view } from '../../stores/view.js';
import { fillIndex } from '../card/fill.jsx';
import { Card } from '../card/card.jsx';
import type { CardKind, Policy } from '../card/card.jsx';
import type { SectionFilter } from './section-filter.jsx';
import { VersionNav, versionTitle } from './version-nav.jsx';
import './list.css';

export interface ListItem {
  iri: string;
  title: string;

  sub: string | null;

  status: string | null;

  offerIris: string[];

  extraBits: string[];

  rules: number;

  kind?: CardKind;

  policy?: Policy;
}

export function rowsOfSets(sets: Policy[], containers: unknown): ListItem[] {
  const m = model();
  const rows = setIndexRows(sets, containers) as Array<Record<string, any>>;
  return rows.map((r) => {
    const bits: string[] = [];
    if (r.versions != null && r.versions > 1) bits.push(text('versions.count', { n: r.versions }));
    if (r.effectiveFrom) bits.push(text('summary.from', { date: r.effectiveFrom }));
    if (r.superseded) bits.push(text('summary.superseded'));
    return {
      iri: r.iri,
      title: r.title,
      sub: r.assignee || null,
      status: policyLifecycle(m, sets[r.idx]) as string,
      offerIris: sets[r.idx]?.offers || [],
      extraBits: bits,
      rules: r.rules || 0,
    };
  });
}

export function rowsOfAgreements(agrs: Policy[]): ListItem[] {
  const m = model();
  return agrs.map((a) => ({
    iri: a.iri,
    title: a.title || a.iri,
    sub: partyLabel(policyAssignee(a)) || null,
    status: policyLifecycle(m, a) as string,
    offerIris: a.offers || [],
    extraBits: [],
    rules: (a.permissions || []).length + (a.prohibitions || []).length
      + (a.obligations || []).length,
    kind: 'agreement' as CardKind,

    policy: a.stub ? a : undefined,
  }));
}

export { corpusKey };

const selfOpened = new Set<string>();
let selfKey: string | null = null;
const [selfVersion, setSelfVersion] = createSignal(0);

function selfOpenedForCorpus(): Set<string> {
  const key = corpusKey();
  if (selfKey !== key) {
    selfOpened.clear();
    selfKey = key;
  }
  return selfOpened;
}

createRoot(() => {
  createEffect(on(listPhase, (phase) => {
    if (phase !== 'first') return;
    selfOpened.clear();
    setSelfVersion((v) => v + 1);
  }));
});

export function rememberedOpen(iri: string): boolean {
  if (listPhase() === 'first') {
    selfVersion();
    return selfOpenedForCorpus().has(iri);
  }
  return isOpen(iri);
}

export function rememberOpen(iri: string, open: boolean): void {
  if (listPhase() === 'first') {
    const s = selfOpenedForCorpus();
    if (open) s.add(iri); else s.delete(iri);
    setSelfVersion((v) => v + 1);
  }
  setOpen(iri, open);
}

function policyOf(iri: string): Policy | null {
  const m = model() as unknown as { sets?: Policy[]; offers?: Policy[]; agreements?: Policy[] } | null;
  if (!m) return null;
  for (const list of [m.sets, m.offers, m.agreements]) {
    const p = (list || []).find((x) => x.iri === iri);
    if (p) return p;
  }
  return null;
}

interface ListCardProps {
  item: ListItem;
  compact?: boolean;

  forceOpen?: boolean;
}

function ListCard(props: ListCardProps): JSX.Element {

  const [versionIri, setVersionIri] = createSignal<string | null>(null);
  const iri = () => versionIri() || props.item.iri;
  const pol = () => policyOf(iri())
    ?? (iri() === props.item.iri ? props.item.policy ?? null : null);
  const [error, setError] = createSignal('');

  const scoped = () => view.policyScope === iri() || view.setScope === iri();
  const open = () => props.forceOpen || scoped() || rememberedOpen(props.item.iri);

  const bits = () => {
    const p = pol();
    const out = [...props.item.extraBits];
    if (!p && props.item.rules && !props.compact) {
      out.unshift(text('rules.count', { n: props.item.rules }));
    }
    return out;
  };

  const [detail] = createResource(
    () => (open() && detailNeeded(pol() ?? { iri: iri() }) ? iri() : undefined),
    async (target: string) => {
      setError('');
      try {
        await fetchDetail(target);
      } catch (e: unknown) {
        setError(text('err.detailLoad', { msg: e instanceof Error ? e.message : String(e) }));
      }

      return null;
    },
  );

  return (
    <>
      <Card
        pol={(pol() || {

          iri: iri(), title: versionTitle(iri()) ?? props.item.title, kind: props.item.kind,
        }) as Policy}
        kind={props.item.kind}
        open={open()}
        lazy
        compact={props.compact}
        detail={view.policyScope === iri()}
        hydrate={() => detail()}
        headerExtra={(
          <>
            <Show when={bits().length}>
              <span class="op-sum muted">{bits().join(' · ')}</span>
            </Show>
            <VersionNav iri={iri()} onSwitch={(to) => setVersionIri(to)} />
          </>
        )}
        onToggle={(on_: boolean) => rememberOpen(props.item.iri, on_)}
      />
      <Show when={error()}><p class="src-err">{error()}</p></Show>
    </>
  );
}

function ownerInList(ref: string, items: ListItem[]): string | null {
  const entry = fillIndex().get(ref);
  for (const sc of (entry && entry.scopes) || []) {
    if (sc.iri && items.some((r) => r.iri === sc.iri)) return sc.iri;
  }
  return null;
}

export interface CardListProps {
  items: ListItem[];
  filter: SectionFilter;

  compact?: boolean;

  onOnthul?: () => void;

  openOnSmallCorpus?: boolean;
}

export function CardList(props: CardListProps): JSX.Element {
  const [count, setCountShown] = createSignal(CARD_CHUNK_SIZE);
  const [forced, setForced] = createSignal<string | null>(null);

  const base = createMemo(() => {
    const q = props.filter.text();
    let out = q
      ? (filterIndexRows(
        props.items.map((r) => ({ ...r, title: r.title, assignee: r.sub })), q,
      ) as unknown as ListItem[])
      : props.items;
    const off = props.filter.offerIri();
    if (off) out = out.filter((r) => r.offerIris.includes(off));
    return out;
  });
  const visible = createMemo(() => base().filter((r) => props.filter.passes(r.status)));
  const shown = createMemo(() => cardChunk(visible(), 0, count()).items as ListItem[]);
  const done = () => count() >= visible().length;

  // Must depend on `state()` only: anything that reads the model restarts the
  // chunks on every rebuild and silently drops the reader back to chunk one.
  createEffect(on(() => props.filter.state(), () => setCountShown(CARD_CHUNK_SIZE),
    { defer: true }));

  createEffect(() => {
    const target = forced();
    if (!target || listPhase() === 'first') return;
    if (shown().some((r) => r.iri === target)) setForced(null);
  });

  createEffect(() => props.filter.setCount(visible().length, props.items.length));

  const more = () => setCountShown((n) => Math.min(n + CARD_CHUNK_SIZE, visible().length));

  const smallCorpus = createMemo(() => !!props.openOnSmallCorpus
    && !refListCollapsed(props.items.length) && listPhase() !== 'first');

  let sentinel!: HTMLDivElement;
  if (typeof IntersectionObserver !== 'undefined') {
    const io = new IntersectionObserver((entries) => {
      if (entries.some((e) => e.isIntersecting) && !done()) more();
    }, { rootMargin: '600px 0px' });

    queueMicrotask(() => { if (sentinel) io.observe(sentinel); });
    onCleanup(() => io.disconnect());
  }

  onCleanup(registerRevealer((ref: string) => {
    const target = props.items.some((r) => r.iri === ref) ? ref : ownerInList(ref, props.items);
    if (!target) return false;
    props.onOnthul?.();
    if (!visible().some((r) => r.iri === target)) props.filter.clear();
    const i = visible().findIndex((r) => r.iri === target);
    if (i < 0) return false;
    if (i >= count()) setCountShown(i + 1);
    setForced(target);

    rememberOpen(target, true);
    return true;
  }));

  return (
    <div class="set-cards">
      <div class="set-card-list">
        <For each={shown()}>{(item) => (
          <ListCard
            item={item}
            compact={props.compact}
            forceOpen={forced() === item.iri || smallCorpus()}
          />
        )}</For>
      </div>
      <div class="card-sentinel" aria-hidden="true" hidden={done()} ref={sentinel} />
      <button type="button" class="btn card-more" hidden={done()} onClick={more}>
        {text('list.loadMoreRest', { n: visible().length - count() })}
      </button>
    </div>
  );
}
