export function emptyListNotice(errors: CorpusError[]): string {
  const base = text('err.noPolicies');
  if (!errors.length) return base;
  const place = (f: CorpusError) => (f.name || f.url || '') + (f.line ? ':' + f.line : '');
  return base + text('err.parseErrors', {
    list: errors.map((f) => `${place(f)} (${f.message})`).join('; '),
  });
}

export function EmptyStart(): JSX.Element {
  return (
    <Show when={loadStatus() === 'empty'}>
      <p class="list-empty-start muted" role="status">
        {text('start.empty')}
        {' '}
        <a class="src-examples" href={exampleSearchString()}>{text('src.examples')}</a>
      </p>
    </Show>
  );
}

interface NavNode { id: string; kind?: string; children?: NavNode[] }

export function sectionCount(n: number): string {
  return listPhase() === 'first' ? '· …' : '· ' + num(n);
}

export interface SectionProps {
  id: string;
  title: string;

  count?: number;
  filter?: SectionFilter;

  /** A command and not an `open` prop: a latch stops Solid writing the
   *  attribute, and a section the reader collapsed never reopens. */
  hook?: (openMe: () => void) => void;
  children: JSX.Element;
}

export function Section(props: SectionProps): JSX.Element {

  const [isOpen, setOpen] = createSignal(true);
  props.hook?.(() => setOpen(true));
  return (
    <>
      <details
        class={'page-section' + (!isOpen() && props.filter ? ' has-detached-filter' : '')}
        id={props.id}
        open={isOpen()}
        onToggle={(e) => setOpen(e.currentTarget.open)}
      >
        <summary class="page-sec-summary" {...headerControls()}>
          <h2 class="page-sec-title">{props.title}</h2>
          <span class="set-index-count muted">
            {props.filter ? props.filter.countText() : sectionCount(props.count || 0)}
          </span>
          <Show when={props.filter}>{(f) => <FilterButton filter={f()} />}</Show>
          <Chevron large />
        </summary>
        <Show when={isOpen() ? props.filter : undefined}>{(f) => <FilterPanel filter={f()} />}</Show>
        {props.children}
      </details>
      <Show when={!isOpen() ? props.filter : undefined}>{(f) => <FilterPanel filter={f()} />}</Show>
    </>
  );
}

export interface ListHook { filterByOffer: (iri: string) => void }

function ListSection(props: {
  id: string; title: string; items: ReturnType<typeof rowsOfSets>;
  withStatus?: boolean; offers?: () => { iri: string; title: string }[]; compact?: boolean;
  openOnSmallCorpus?: boolean; hook?: (h: ListHook) => void;
}): JSX.Element {

  let openSection: (() => void) | null = null;
  const filter = makeSectionFilter({
    id: props.id, withStatus: props.withStatus, offers: props.offers,
  });

  props.hook?.({
    filterByOffer: (iri: string) => {
      openSection?.();
      filter.setOffer(iri);
      filter.setOpen(true);
    },
  });
  return (
    <Section
      id={props.id}
      title={props.title}
      filter={filter}
      hook={(openMe) => { openSection = openMe; }}
    >
      <CardList
        items={props.items}
        filter={filter}
        compact={props.compact}
        openOnSmallCorpus={props.openOnSmallCorpus}
        onOnthul={() => openSection?.()}
      />
    </Section>
  );
}

function byIri(list: Policy[] | undefined, iri: string): Policy | null {
  return (list || []).find((p) => p.iri === iri) || null;
}

export function Sections(): JSX.Element {

  // No `{ defer: true }`: Solid returns early on a deferred first run without
  // setting prevInput, so the guard below would never open.
  createEffect(on(listPhase, (now, prev) => {
    if (prev === 'first' && now !== 'first') holdAnchor();
  }));

  createEffect(on(model, () => {
    if (!hasPendingAnchor()) return;
    setTimeout(() => { void releaseAnchor(); }, 0);
  }));

  const m = () => model() as unknown as
    { sets?: Policy[]; offers?: Policy[]; agreements?: Policy[]; temporalContainers?: unknown }
    | null;

  const tree = () => (scopedNav() ?? fullNav() ?? []) as NavNode[];

  const offers = createMemo(() => {
    const out: Policy[] = [];
    for (const node of tree()) {
      if (node.kind !== 'offer') continue;
      const o = byIri(m()?.offers, node.id);
      if (o) out.push(o);
    }
    return out;
  });

  const agreements = createMemo(() => {
    const out: Policy[] = [];
    const seen = new Set<string>();
    const add = (id: string) => {
      if (seen.has(id)) return;
      seen.add(id);
      const a = byIri(m()?.agreements, id);
      if (a) out.push(a);
    };
    for (const node of tree()) {
      if (node.kind === 'offer') {
        for (const child of node.children || []) {
          if (child.kind === 'agreement') add(child.id);
        }
      } else if (node.id === '__loose-agreements__') {
        for (const child of node.children || []) add(child.id);
      }
    }
    return out;
  });

  const terminated = createMemo(() => {
    const m2 = m();
    if (!m2) return [];
    const seen = new Set(agreements().map((a) => a.iri));
    const out: Policy[] = [];
    for (const c of stubOnlyContainers(m2, 'agreement') as unknown[]) {
      const v = containerCardVersion(c) as Version | null;
      if (!v || seen.has(v.iri)) continue;
      seen.add(v.iri);
      out.push(stubPolicy(v));
    }
    return out;
  });

  const policies = createMemo(() => {
    const out: Policy[] = [];
    for (const node of tree()) {
      if (node.kind !== 'set') continue;
      if (view.policyScope && node.id !== view.policyScope) {
        const child = (node.children || []).find((k) => k.id === view.policyScope);
        if (child) {
          const p = byIri(m()?.sets, child.id);
          if (p) { out.push(p); continue; }
        }
      }
      const p = byIri(m()?.sets, node.id);
      if (p) out.push(p);
    }
    return out;
  });
  const sets = createMemo(() => policies().filter((p) => !p.isRequest));
  const requests = createMemo(() => policies().filter((p) => p.isRequest));

  const agreementRows = createMemo(() => rowsOfAgreements([
    ...agreements(), ...terminated(),
  ]));
  const setRows = createMemo(() => rowsOfSets(sets(), m()?.temporalContainers));
  const requestRows = createMemo(() => rowsOfSets(requests(), m()?.temporalContainers));

  const offerOptions = () => offers().map((o) => ({ iri: o.iri, title: o.title || o.iri }));
  const empty = () => !offers().length && !agreements().length && !terminated().length
    && !sets().length && !requests().length;

  let hook: ListHook | null = null;

  const AgreementCount = (props: { offer: Policy }) => {
    const n = () => agreements().filter((a) => (a.offers || []).includes(props.offer.iri)).length;
    return (
      <Show when={n()}>
        <span class="op-sum muted">
                    <Show when={countRules(props.offer)}>{' · '}</Show>
          <a
            class="agr-count-link"
            href="#section-agreements"
            title={text('agreements.countTitle')}
            onClick={(e) => {
              e.stopPropagation();
              hook?.filterByOffer(props.offer.iri);
            }}
          >
                        {endpoint()
              ? text('agreements.shown', { n: n() })
              : text('agreements.count', { n: n() })}
          </a>
        </span>
      </Show>
    );
  };

  const OfferCard = (props: { offer: Policy; anchor: string }) => {
    const [versionIri, setVersionIri] = createSignal<string | null>(null);
    const iri = () => versionIri() || props.offer.iri;

    const shown = (): Policy => {
      if (iri() === props.offer.iri) return props.offer;
      const all = [...(m()?.offers || []), ...(m()?.sets || []), ...(m()?.agreements || [])];
      return all.find((p) => p.iri === iri())
        ?? ({ iri: iri(), title: versionTitle(iri()), kind: 'offer' } as Policy);
    };
    return (
      <Card
        pol={shown()}
        kind="offer"
        anchor={props.anchor}
        lazy
        open={view.policyScope === iri() || rememberedOpen(props.offer.iri)}
        detail={view.policyScope === iri()}

        headerExtra={(
          <>
            <AgreementCount offer={props.offer} />
            <VersionNav iri={iri()} onSwitch={(to) => setVersionIri(to)} />
          </>
        )}
        onToggle={(on_: boolean) => rememberOpen(props.offer.iri, on_)}
      />
    );
  };

  return (
    <Show when={m()} fallback={<EmptyStart />}>
                  <Show when={offers().length || editLayerActive()}>
        <Section id="section-offers" title={text('section.offers')} count={offers().length}>
                    <Hook name="newPolicy" ctx={{}} />
          <For each={offers()}>{(o, i) => (
            <OfferCard offer={o} anchor={'offer-' + i()} />
          )}</For>
        </Section>
      </Show>

      <Show when={agreementRows().length}>
        <ListSection
          id="section-agreements"
          title={text('section.agreements')}
          items={agreementRows()}
          offers={offerOptions}
          openOnSmallCorpus
          hook={(h) => { hook = h; }}
        />
      </Show>

      <Show when={requests().length}>
        <ListSection
          id="section-requests"
          title={text('section.requests')}
          items={requestRows()}

          withStatus={false}
          compact
        />
      </Show>

      <Show when={sets().length}>
        <ListSection
          id="section-sets"
          title={text('section.sets')}
          items={setRows()}
        />
      </Show>

      <Show when={empty()}>
        <p class="src-err">{emptyListNotice(errors())}</p>
      </Show>
    </Show>
  );
}
