import { createEffect, createSignal, Show, Suspense } from 'solid-js';
import type { JSX } from 'solid-js';
import { versionNavModel } from '../../model/parse.js';
import { model } from '../../stores/corpus.js';
import { text } from '../../stores/view.js';
import { PRED, Field } from '../edit/hooks.jsx';
import { Chevron, KindPill, VersionChip } from '../shared/chip.jsx';
import type { CardKind } from '../shared/chip.jsx';
import { CardBody } from './body-rows.jsx';
import { ChipSpace } from './constraint-content.jsx';
import type { ExtraProperty } from './body-rows.jsx';
import { Rules } from './rules.jsx';
import './card.css';
import { headerControls } from '../shared/header-selection.js';
import { scrollSyncAfterExpand } from '../shared/scroll-sync.js';
import { focusAddress, ghostRevealClass, Hook } from '../shared/edit-hook.jsx';

export type { CardKind };
export type { ExtraProperty };

export interface Reference {
  iri: string;
  curie?: string | null;
  label?: string | null;
  title?: string | null;
}

export interface Party {
  iri?: string | null;
  curie?: string | null;
  label?: string | null;
  desc?: string;
  anon?: boolean;
}

export interface Version {
  effectiveFrom?: string | null;
  effectiveTo?: string | null;
  revisionOf?: Reference | null;
  supersededBy?: Reference[];
  derivedFrom?: Reference[];
}

export type RuleAction = { iri?: string | null; curie?: string | null; label?: string; desc?: string };

export interface Rule {
  iri: string | null;
  title?: string | null;
  label?: string | null;
  description?: string | null;
  action?: RuleAction | string | null;
  purpose?: (RuleAction & { operatorWord?: string }) | null;
  targets?: Party[];
  assignee?: Party | null;
  informedParty?: Party | null;
  primarySources?: Reference[];
  constraints?: unknown[];
  refinements?: unknown[];
  duties?: Rule[];
  extraProps?: ExtraProperty[];
  kind?: string;
}

export interface Policy {
  iri: string;
  kind?: string;
  curie?: string | null;
  anon?: boolean;
  stub?: boolean;
  isRequest?: boolean;
  title?: string | null;
  description?: string | null;
  identifier?: string | null;
  issued?: string | null;
  profile?: string | null;
  assigner?: Party | null;
  assignee?: Party | null;
  offers?: string[];
  requests?: Reference[];
  asksFor?: Reference[];
  datasetIri?: string | null;
  permissions?: Rule[];
  prohibitions?: Rule[];
  obligations?: Rule[];
  version?: Version | null;
  extraProps?: ExtraProperty[];
}

export function kindOf(pol: Policy): CardKind {
  if (pol.kind === 'offer') return 'offer';
  if (pol.kind === 'agreement') return 'agreement';
  return pol.isRequest ? 'request' : 'set';
}

const CARD_CLASS: Record<CardKind, string> = {
  offer: 'offer-group',
  agreement: 'agr-group',
  set: 'offer-group set-card',
  request: 'offer-group set-card',
};
const SUMMARY_CLASS: Record<CardKind, string> = {
  offer: 'offer-summary', agreement: 'agr-summary',
  set: 'offer-summary', request: 'offer-summary',
};
const TITLE_CLASS: Record<CardKind, string> = {
  offer: 'offer-title', agreement: 'agr-title',
  set: 'offer-title', request: 'offer-title',
};

export function countRules(pol: Policy): number {
  return (pol.obligations || []).length + (pol.permissions || []).length
    + (pol.prohibitions || []).length;
}

export function versionStatus(pol: Policy): string | null {
  if (pol.anon || !pol.iri) return null;
  const nm = versionNavModel(model(), pol.iri) as { shown?: { status?: string } } | null;
  return (nm && nm.shown && nm.shown.status) || null;
}

export function assigneeBeside(pol: Policy): string | null {
  const name = pol.assignee && pol.assignee.label;
  if (!name) return null;
  return (pol.title || '').includes(name) ? null : name;
}

export interface CardProps {
  pol: Policy;
  kind?: CardKind;
  anchor?: string;
  open?: boolean;
  compact?: boolean;
  detail?: boolean;
  headerExtra?: JSX.Element;
  lazy?: boolean;
  onToggle?: (open: boolean) => void;
  hydrate?: () => unknown;
}

export function CardLoading(): JSX.Element {
  return (
    <div class="card-loading">
      <span class="sr-only" role="status" aria-live="polite">{text('load.cardDetail')}</span>
      <div class="skel-lines" aria-hidden="true">
        <span class="skel skel-line skel-v0" />
        <span class="skel skel-line skel-v1" />
        <span class="skel skel-line skel-v2" />
      </div>
    </div>
  );
}

export function Card(props: CardProps): JSX.Element {
  const kind = () => props.kind ?? kindOf(props.pol);
  const count = () => countRules(props.pol);
  // Once built, stays built: collapsing keeps the body so reopening costs nothing.
  const [built, setBuilt] = createSignal(!props.lazy || !!props.open);
  createEffect(() => { if (props.open) setBuilt(true); });
  return (
    <details
      // Ghost reveal sits on the card root; on the ghost itself it would reveal only itself.
      class={CARD_CLASS[kind()] + ghostRevealClass()}
      id={props.anchor}
      data-iri={props.pol.iri || undefined}
      data-ref={props.pol.iri || undefined}
      open={props.open}
      onToggle={(e) => {
        const nowOpen = e.currentTarget.open;
        if (nowOpen) setBuilt(true);
        props.onToggle?.(nowOpen);
        if (nowOpen) scrollSyncAfterExpand(e.currentTarget);
      }}
    >
      <summary class={SUMMARY_CLASS[kind()]} {...headerControls()}>
        <KindPill kind={kind()} />
        <ChipSpace />

        <span class={TITLE_CLASS[kind()]}>
          <Field spec={{
            term: props.pol.anon ? (props.pol as { term?: unknown }).term : props.pol.iri,
            kind: 'text',
            preds: PRED.TITLE,
            value: props.pol.title,
            hint: text('edit.hintTitle'),
            focusKey: focusAddress(props.pol.anon
              ? (props.pol as { term?: unknown }).term : props.pol.iri),
          }}
          >{props.pol.title}</Field>
        </span>

        <Show when={props.pol.anon ? (props.pol as { term?: unknown }).term : props.pol.iri}>
          <Field spec={{
            term: props.pol.anon ? (props.pol as { term?: unknown }).term : props.pol.iri,
            kind: 'iri',
            preds: [],
            variant: 'nodeIri',
            iri: props.pol.anon ? null : props.pol.iri,
          }}
          />
        </Show>
        <Show when={kind() === 'agreement' && assigneeBeside(props.pol)}>{(name) => (
          <><ChipSpace /><span class="agr-assignee muted">{name()}</span></>
        )}</Show>
        <ChipSpace />
        <VersionChip status={versionStatus(props.pol)} />
        <ChipSpace />
        <Show when={!props.compact && count()}>
          <ChipSpace />
          <span class="op-sum muted">{text('rules.count', { n: count() })}</span>
        </Show>
        {props.headerExtra}
        <Hook name="cardHeader" ctx={{ pol: props.pol, kind: kind() }} />
        <Chevron />
      </summary>
      <Show when={built()}>
        <Suspense fallback={<CardLoading />}>
          {props.hydrate?.() as JSX.Element}
          <CardBody pol={props.pol} kind={kind()} compact={props.compact} detail={props.detail} />
          <Rules pol={props.pol} kind={kind()} />
        </Suspense>
      </Show>
    </details>
  );
}
