import { localName, t } from '../../model-boundary.js';
import type { PredicateHeader, Reference } from '../../model-boundary.js';

export function refRowText(ref: Partial<Reference>): { title: string; pred: string } {
  return {
    title: ref.label || ref.curie || (ref.iri ? localName(ref.iri) : t('anon')),
    pred: predicateText(ref.predicate),
  };
}

export function predicateText(p?: Partial<PredicateHeader> | null): string {
  if (!p) return '';
  return p.label && p.label !== p.curie ? `${p.label} (${p.curie})` : (p.curie || '');
}
