import { For, Show, createMemo } from 'solid-js';
import type { JSX } from 'solid-js';
import { offerRuleSplit } from '../../model/parse.js';
import { model } from '../../stores/corpus.js';
import { text } from '../../stores/view.js';
import { Chevron, RuleBadge } from '../shared/chip.jsx';
import type { RuleKind } from '../shared/chip.jsx';
import { ChipSpace } from './constraint-content.jsx';
import { TermHeader } from '../shared/header.jsx';
import { editLayerActive, Hook } from '../shared/edit-hook.jsx';
import type { Policy, Rule } from './card.jsx';
import { headerControls } from '../shared/header-selection.js';

export type RowBuilder = (rule: Rule, kind: RuleKind, mark?: string | null) => JSX.Element;

type DutyRule = Rule & { consequences?: Rule[] };

export interface Parent {
  iri?: string | null;
  curie?: string | null;
  title?: string | null;
  literal?: string | null;
  present?: boolean;
  cycle?: boolean;
  rules?: { rule: Rule; type: string }[];
}

type Split = {
  fromOffer: { rule: Rule; type: string }[];
  own: { obligations: Rule[]; permissions: Rule[]; prohibitions: Rule[] };
  offers: { iri: string; title?: string | null }[];
};

// The RuleKind values ('permission', 'prohibition', 'offer', 'inherited') also spell CSS
// classes and badge names: renaming them changes the DOM.
function kindOfItem(type: string): RuleKind {
  if (type === 'obligation') return 'duty';
  return type === 'prohibition' ? 'prohibition' : 'permission';
}

const NOUN_KEY: Record<string, string> = {
  duty: 'noun.duty', permission: 'noun.permission', prohibition: 'noun.prohibition',
};
const NOUN_ORDER: RuleKind[] = ['duty', 'permission', 'prohibition'];

export function offerLabel(items: { type: string }[]): string {
  const counts = new Map<RuleKind, number>();
  for (const e of items) {
    const k = kindOfItem(e.type);
    counts.set(k, (counts.get(k) || 0) + 1);
  }
  const parts = NOUN_ORDER.filter((k) => counts.get(k))
    .map((k) => text(NOUN_KEY[k], { n: counts.get(k) }));
  return text('offerRules.label', { parts: parts.join(', ') });
}

export function inheritedLabel(g: Parent, lazy = false): string {
  if (!g.iri) return text('inheritRules.labelInvalid', { value: g.literal });
  const parent = g.title || g.curie || g.iri;
  if (!g.present) return text('inheritRules.labelMissing', { parent: parent });
  const n = (g.rules || []).length;
  if (n) return text('inheritRules.label', { parent: parent, n });
  return lazy ? text('inheritRules.labelLazy', { parent: parent })
    : text('inheritRules.labelEmpty', { parent: parent });
}

function split(pol: Policy): Split {
  return offerRuleSplit(model(), pol) as Split;
}

function parentRules(g: Parent): { rule: Rule; type: string }[] {
  return g.rules || [];
}

export function ownRules(pol: Policy): { rule: Rule; kind: RuleKind }[] {
  const s = split(pol);
  return [
    ...s.own.permissions.map((r) => ({ rule: r, kind: 'permission' as RuleKind })),
    ...s.own.prohibitions.map((r) => ({ rule: r, kind: 'prohibition' as RuleKind })),
  ];
}

function ownRuleCount(pol: Policy): number {
  return (pol.obligations || []).length + (pol.permissions || []).length
    + (pol.prohibitions || []).length;
}

export function showsRules(pol: Policy): boolean {
  return ownRuleCount(pol) > 0
    || ((pol as { inherited?: Parent[] }).inherited || []).length > 0;
}

export interface OfferSection {
  offer: { iri: string; title?: string | null } | null;
  rules: Rule[];
}

function fulfilledOffers(pol: Policy): Policy[] {
  const all = ((model() as { offers?: Policy[] } | null)?.offers) || [];
  return (pol.offers || [])
    .map((iri) => all.find((o) => o.iri === iri))
    .filter((o): o is Policy => !!o);
}

function actionIri(rule: Rule): string | null {
  const a = rule.action;
  if (!a || typeof a === 'string') return null;
  return a.iri || null;
}

export function offerSections(pol: Policy): OfferSection[] | null {
  const offerPolicies = fulfilledOffers(pol);
  if (offerPolicies.length < 2) return null;
  const perms = split(pol).own.permissions;
  if (!perms.length) return null;
  const rest = new Set(perms);
  const out: OfferSection[] = [];
  for (const off of offerPolicies) {
    const ruleIris = new Set((off.permissions || []).map((r) => r.iri).filter(Boolean));
    const actions = new Set((off.permissions || []).map(actionIri).filter(Boolean));
    const own = perms.filter((p) => {
      const df = (p as { derivedFrom?: string[] }).derivedFrom || [];
      if (df.includes(off.iri) || df.some((iri) => ruleIris.has(iri))) return true;
      if (df.length) return false;
      const a = actionIri(p);
      return !!(a && actions.has(a));
    });
    if (!own.length) continue;
    own.forEach((p) => rest.delete(p));
    out.push({ offer: { iri: off.iri, title: off.title }, rules: own });
  }
  if (rest.size) out.push({ offer: null, rules: [...rest] });
  return out;
}

export function ownDuties(pol: Policy): { rules: Rule[]; additional: boolean } {
  const s = split(pol);
  return {
    rules: s.own.obligations,
    additional: s.fromOffer.some((e) => e.type === 'obligation'),
  };
}

export function OfferFold(props: {
  pol: Policy;
  row: RowBuilder;
  offerLink?: (offer: { iri: string; title?: string | null }) => JSX.Element;
}): JSX.Element {
  const s = createMemo(() => split(props.pol));
  return (
    <Show when={s().fromOffer.length > 0}>
      <div class="op-list">
        <details class="op-row offer">
          <summary class="op-summary" {...headerControls()}>
            <RuleBadge kind="offer" />
            <ChipSpace />
            <span class="op-title">
              <span class="op-name">{offerLabel(s().fromOffer)}</span>
              <For each={s().offers}>{(off, i) => (
                <>
                  {i() ? ', ' : ' '}
                  {props.offerLink
                    ? props.offerLink(off)
                    : <span class="muted">{off.title}</span>}
                </>
              )}</For>
            </span>
            <Chevron />
          </summary>
          <div class="op-body">
            <p class="duty-sub muted">{text('offerRules.note')}</p>
            <div class="op-list">
              <For each={s().fromOffer}>{(e) => (
                props.row(e.rule, kindOfItem(e.type))
              )}</For>
            </div>
          </div>
        </details>
      </div>
    </Show>
  );
}

export function InheritedFold(props: { pol: Policy; row: RowBuilder }): JSX.Element {
  const parents = () => ((props.pol as { inherited?: Parent[] }).inherited || []);
  return (
    <Show when={parents().length}>
      <div class="op-list">
        <For each={parents()}>{(g) => (
          <details class={'op-row inherited' + (g.present ? '' : ' missing-value')}>
            <summary class="op-summary" {...headerControls()}>
              <RuleBadge kind="inherited" />
              <ChipSpace />
              <span class="op-title">
                <span class="op-name">{inheritedLabel(g)}</span>
                <Show when={g.present && g.curie && !/^https?:/.test(g.curie as string)
                  && g.curie !== g.title}
                >
                  <ChipSpace />
                  <span class="op-path mono muted">{g.curie}</span>
                </Show>
                <Show when={g.cycle}>
                  <ChipSpace />
                  <span class="op-path muted" title={text('inheritRules.cycleTitle')}>
                    {text('inheritRules.cycle')}
                  </span>
                </Show>
              </span>
              <ChipSpace />
              <Chevron />
            </summary>
            <div class="op-body">
              <p class="duty-sub muted">
                {g.present ? text('inheritRules.note') : text('inheritRules.noteMissing')}
              </p>
              <div class="op-list">
                <For each={parentRules(g)}>{(e) => (
                  props.row(e.rule, kindOfItem(e.type))
                )}</For>
              </div>
            </div>
          </details>
        )}</For>
      </div>
    </Show>
  );
}

export function Duties(props: {
  rule: Rule; row: RowBuilder; kind?: RuleKind;
}): JSX.Element {
  const list = () => (props.rule.duties || []);
  return (
    <Show when={list().length || editLayerActive()}>
      <TermHeader tag="h4" key="head.duties" />
      <div class="op-list">
        <For each={list()}>{(d) => props.row(d, 'duty')}</For>
        <Hook
          name="dutyGhost"
          ctx={{ rule: props.rule, kind: props.kind ?? 'duty' }}
        />
      </div>
    </Show>
  );
}

export function Consequences(props: { rule: Rule; row: RowBuilder }): JSX.Element {
  const list = () => ((props.rule as DutyRule).consequences || []);
  return (
    <Show when={list().length}>
      <TermHeader tag="h4" key="head.consequences" />
      <div class="op-list">
        <For each={list()}>{(d) => props.row(d, 'duty')}</For>
      </div>
    </Show>
  );
}
